// 原TravelCatalog的有限作者行；JSON导出与无树shape共享同一emit。
#include "cargo_handling.hpp"
#include "movement_exact_detail.hpp"
#include "resident/checkpoint/projection_writer.hpp"
#include <set>
namespace hanmo::resident {using namespace movement_detail;namespace {
using Value=BoundaryValue;
const Value& required(const Value& v,const char* name){const auto* out=v.find(name);if(!out)fail("CargoHandlingAuthorFieldRequired",name);return *out;}
template<class T>const T& typed(const Value& v,const StableId& path){const auto* out=v.as<T>();if(!out)fail("CargoHandlingAuthorTypeMismatch",path);return *out;}
StableId text(const Value& v,const char* name){return typed<StableId>(required(v,name),name);}
Integer number(const Value& v,const char* name){return typed<Integer>(required(v,name),name);}
void fields(const Value& v,std::initializer_list<const char*> allowed){for(const auto& row:typed<Value::Dict>(v,"rule")){bool known=false;for(const auto* key:allowed)if(row.first==key)known=true;if(!known)fail("UnsupportedCargoHandlingAuthorField",row.first);}}
std::vector<StableId> strings(const Value& v){std::vector<StableId> out;std::set<StableId> unique;for(const auto& row:typed<Value::Array>(v,"list")){auto id=typed<StableId>(row,"list/item");if(id.empty()||!unique.insert(id).second)fail("InvalidCargoHandlingAuthorList",id);out.push_back(std::move(id));}return out;}
SourceRef source(const Value& v){fields(v,{"domain","kind","id"});SourceRef out{text(v,"domain"),text(v,"kind"),text(v,"id")};if(!source_valid(out))fail("CargoHandlingAuthorSourceRequired");return out;}
Status emit_source(ProjectionWriter& w,std::string_view name,const SourceRef& v){return w.object(name,[&](auto& x){x.field("domain",v.domain);x.field("kind",v.kind);return x.field("id",v.id);});}
Status emit_strings(ProjectionWriter& w,std::string_view name,const std::vector<StableId>& values){return w.sequence(name,values,[](auto& x,const auto& id){return x.field("",id);});}
}
Outcome<OrderedTable<CargoHandlingRule>> decode_cargo_handling_rules(const BoundaryValue& value){return guard<OrderedTable<CargoHandlingRule>>([&]{OrderedTable<CargoHandlingRule> out;for(const auto& row:typed<Value::Dict>(value,"cargo_handling_rules")){const auto& v=row.second;fields(v,{"id","version","allowed_carrier_kinds","allowed_operations","allowed_business_kinds","allowed_cargo_classes","handling_half_days","required_workers","labor_modes","required_capability_purpose_ref","facility_requirement_ref","cost_rule_ref","interruption_rule_ref"});CargoHandlingRule r;r.id=text(v,"id");r.version=number(v,"version");if(row.first!=r.id)fail("CargoHandlingAuthorIdMismatch",row.first);r.allowed_carrier_kinds=strings(required(v,"allowed_carrier_kinds"));for(const auto& op:strings(required(v,"allowed_operations"))){if(op=="Load")r.allowed_operations.push_back(CargoHandlingOperation::load);else if(op=="Unload")r.allowed_operations.push_back(CargoHandlingOperation::unload);else fail("InvalidCargoHandlingOperation",op);}r.allowed_business_kinds=strings(required(v,"allowed_business_kinds"));r.allowed_cargo_classes=strings(required(v,"allowed_cargo_classes"));r.handling_half_days=number(v,"handling_half_days");r.required_workers=number(v,"required_workers");for(const auto& mode:strings(required(v,"labor_modes"))){if(mode=="NamedWorkers")r.labor_modes.push_back(CargoHandlingLaborMode::named_workers);else if(mode=="CohortWorkers")r.labor_modes.push_back(CargoHandlingLaborMode::cohort_workers);else fail("InvalidCargoHandlingLaborMode",mode);}if(const auto* x=v.find("required_capability_purpose_ref"))r.required_capability_purpose_ref=typed<StableId>(*x,"required_capability_purpose_ref");if(const auto* x=v.find("facility_requirement_ref"))r.facility_requirement_ref=typed<StableId>(*x,"facility_requirement_ref");r.cost_rule_ref=source(required(v,"cost_rule_ref"));r.interruption_rule_ref=source(required(v,"interruption_rule_ref"));take(validate_cargo_handling_rule(r));if(!out.insert(row.first,std::move(r)))fail("DuplicateCargoHandlingRule",row.first);}return out;});}
Status emit_cargo_handling_rule_projection(ProjectionWriter& w,std::string_view name,const CargoHandlingRule& r){auto valid=validate_cargo_handling_rule(r);if(!valid.ok)return valid;return w.object(name,[&](auto& x){x.field("id",r.id);x.field("version",r.version);emit_strings(x,"allowed_carrier_kinds",r.allowed_carrier_kinds);x.sequence("allowed_operations",r.allowed_operations,[](auto& a,auto op){return a.field("",StableId{op==CargoHandlingOperation::load?"Load":"Unload"});});emit_strings(x,"allowed_business_kinds",r.allowed_business_kinds);emit_strings(x,"allowed_cargo_classes",r.allowed_cargo_classes);x.field("handling_half_days",r.handling_half_days);x.field("required_workers",r.required_workers);x.sequence("labor_modes",r.labor_modes,[](auto& a,auto mode){return a.field("",StableId{mode==CargoHandlingLaborMode::named_workers?"NamedWorkers":"CohortWorkers"});});if(r.required_capability_purpose_ref)x.field("required_capability_purpose_ref",*r.required_capability_purpose_ref);if(r.facility_requirement_ref)x.field("facility_requirement_ref",*r.facility_requirement_ref);emit_source(x,"cost_rule_ref",r.cost_rule_ref);emit_source(x,"interruption_rule_ref",r.interruption_rule_ref);return x.status();});}
Outcome<BoundaryValue> export_cargo_handling_rules(const OrderedTable<CargoHandlingRule>& rules){return guard<BoundaryValue>([&]{BoundaryValue out;BoundaryProjectionWriter w(out);take(w.object("",[&](auto& x){for(const auto& row:rules.rows())take(emit_cargo_handling_rule_projection(x,row.first,row.second));return x.status();}));take(w.finish());return out;});}
}
